// Test the safemax implementation
template <class T>
const T& safemax(const T& a, const T& b) {
    if (std::isnan(a)) return b;
    if (std::isnan(b)) return a;
    return (a > b) ? a : b;
}

// Test cases
int main() {
    // Normal cases
    float a = 3.0f, b = 5.0f;
    float result1 = safemax(a, b);  // Should be 5.0

    // NaN cases
    float nan_val = std::nan("");
    float result2 = safemax(nan_val, b);  // Should be 5.0 (b)
    float result3 = safemax(a, nan_val);  // Should be 3.0 (a)
    float result4 = safemax(nan_val, nan_val);  // Should be NaN

    // Verify results
    bool test1 = (result1 == 5.0f);
    bool test2 = (result2 == 5.0f);
    bool test3 = (result3 == 3.0f);
    bool test4 = std::isnan(result4);

    return (test1 && test2 && test3 && test4) ? 0 : 1;
}

